/**
 * rsa-pss.ts - RSA-PSS Signatures (Teaching Model)
 *
 * ---------------------------------------------------------------------------
 * What it does
 * ---------------------------------------------------------------------------
 * RSA-PSS signs a message by formatting an encoded message with a random salt,
 * a hash of the padded message, and a mask generated by MGF1, then applying
 * the RSA private operation. Verification reverses the mask, checks the
 * separator byte and padding, and recomputes the inner hash. Unlike the older
 * PKCS#1 v1.5 padding, PSS has a reduction proof to the RSA problem.
 *
 * ---------------------------------------------------------------------------
 * Complexity
 *   Time:  O(log n) modular multiplications plus O(emLen) hashing
 *   Space: O(emLen) bytes for the encoded message
 *
 * ---------------------------------------------------------------------------
 * Visualization mapping
 *   - Array bars show the message hash, the signature residue, and the verdict.
 *   - meta carries the modulus, the salt, and the verification result.
 *
 * ---------------------------------------------------------------------------
 * Note
 *   - This is a TOY MODEL. The hash and moduli are tiny and the scheme is not
 *     secure. It faithfully follows the PSS structure so the encoding steps
 *     can be studied, but it must never be used to protect real data.
 */

import type { AlgorithmModule, EntityState, VisualEntity, VisualFrame } from "@/types";

const H_LEN = 8;
const S_LEN = 8;

/** Modular exponentiation with BigInt. */
export function powMod(base: bigint, exponent: bigint, modulus: bigint): bigint {
    let result = 1n;
    let b = ((base % modulus) + modulus) % modulus;
    let e = exponent;
    while (e > 0n) {
        if (e % 2n === 1n) result = (result * b) % modulus;
        b = (b * b) % modulus;
        e /= 2n;
    }
    return result;
}

/** Extended Euclidean inverse modulo m. */
export function modInverse(a: bigint, m: bigint): bigint {
    let oldR = ((a % m) + m) % m;
    let r = m;
    let oldS = 1n;
    let s = 0n;
    while (r !== 0n) {
        const q = oldR / r;
        [oldR, r] = [r, oldR - q * r];
        [oldS, s] = [s, oldS - q * s];
    }
    if (oldR !== 1n) return 0n;
    return ((oldS % m) + m) % m;
}

/** Deterministic Miller-Rabin for the toy key sizes used here. */
export function isPrimeBig(n: bigint): boolean {
    if (n < 2n) return false;
    for (const p of [2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n]) {
        if (n === p) return true;
        if (n % p === 0n) return false;
    }
    let d = n - 1n;
    let s = 0;
    while (d % 2n === 0n) {
        d /= 2n;
        s += 1;
    }
    for (const a of [2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n]) {
        let x = powMod(a, d, n);
        if (x === 1n || x === n - 1n) continue;
        let witness = false;
        for (let i = 1; i < s; i += 1) {
            x = (x * x) % n;
            if (x === n - 1n) {
                witness = true;
                break;
            }
        }
        if (!witness) return false;
    }
    return true;
}

/** Next prime at or above n. */
export function nextPrime(n: bigint): bigint {
    let candidate = n % 2n === 0n ? n + 1n : n;
    while (!isPrimeBig(candidate)) candidate += 2n;
    return candidate;
}

/** A small deterministic hash returning exactly H_LEN bytes. */
export function toyHash(bytes: number[]): number[] {
    let state = 0xcbf29ce484222325n;
    const bound = 1n << 64n;
    for (const byte of bytes) {
        state = ((state ^ BigInt(byte & 0xff)) * CONST_MASK) % bound;
    }
    state = ((state ^ (state >> 29n)) * 0xbf58476d1ce4e5b9n) % bound;
    state = (state ^ (state >> 27n)) % bound;
    const out: number[] = [];
    for (let i = 0; i < H_LEN; i += 1) {
        out.push(Number(state & 0xffn));
        state >>= 8n;
    }
    return out;
}

const CONST_MASK = 0x100000001b3n;

/** MGF1 using the toy hash: expand a seed to a requested byte length. */
export function mgf1(seed: number[], length: number): number[] {
    const out: number[] = [];
    let counter = 0;
    while (out.length < length) {
        const block = [...seed, (counter >> 24) & 0xff, (counter >> 16) & 0xff, (counter >> 8) & 0xff, counter & 0xff];
        out.push(...toyHash(block));
        counter += 1;
    }
    return out.slice(0, length);
}

const xorBytes = (a: number[], b: number[]): number[] => a.map((value, i) => (value ^ (b[i] ?? 0)) & 0xff);

/** EMSA-PSS encode: produce an encoded message of emLen bytes. */
export function pssEncode(messageHash: number[], emBits: number, salt: number[]): number[] {
    const emLen = Math.ceil(emBits / 8);
    if (emLen < H_LEN + salt.length + 2) throw new Error("Encoded message is too short.");
    const inner = [...new Array<number>(8).fill(0), ...messageHash, ...salt];
    const h = toyHash(inner);
    const mask = mgf1(h, emLen - salt.length - 1);
    const ps = new Array<number>(emLen - salt.length - H_LEN - 2).fill(0);
    const db = [...ps, 0x01, ...salt];
    const maskedDb = xorBytes(db, mask);
    const unused = 8 * emLen - emBits;
    if (unused > 0) maskedDb[0] = (maskedDb[0] ?? 0) & (0xff >> unused);
    return [...maskedDb, ...h, 0xbc];
}

/** EMSA-PSS verify: check a recovered encoded message against a hash. */
export function pssVerify(em: number[], messageHash: number[], emBits: number, saltLen = S_LEN): boolean {
    const emLen = Math.ceil(emBits / 8);
    if (em.length !== emLen || em[emLen - 1] !== 0xbc) return false;
    const unused = 8 * emLen - emBits;
    if (unused > 0 && ((em[0] ?? 0) & (0xff << (8 - unused))) !== 0) return false;
    const maskedDb = em.slice(0, emLen - H_LEN - 1);
    const h = em.slice(emLen - H_LEN - 1, emLen - 1);
    const mask = mgf1(h, emLen - saltLen - 1);
    const db = xorBytes(maskedDb, mask);
    if (unused > 0) db[0] = (db[0] ?? 0) & (0xff >> unused);
    const psLen = emLen - saltLen - H_LEN - 2;
    for (let i = 0; i < psLen; i += 1) if (db[i] !== 0) return false;
    if (db[psLen] !== 0x01) return false;
    const salt = db.slice(psLen + 1);
    const inner = [...new Array<number>(8).fill(0), ...messageHash, ...salt];
    const recomputed = toyHash(inner);
    return recomputed.every((value, i) => value === h[i]);
}

export interface ToyRsaKey {
    n: bigint;
    e: bigint;
    d: bigint;
    lambda: bigint;
    emBits: number;
}

/** Generate a deterministic toy RSA key with enough room for PSS. */
export function rsaPssKeygen(): ToyRsaKey {
    const p = nextPrime(1n << 79n);
    let q = nextPrime((1n << 79n) + 1000000007n);
    const e = 65537n;
    let lambda = (p - 1n) * (q - 1n) / gcdBig(p - 1n, q - 1n);
    while (gcdBig(e, lambda) !== 1n) {
        q = nextPrime(q + 2n);
        lambda = (p - 1n) * (q - 1n) / gcdBig(p - 1n, q - 1n);
    }
    const n = p * q;
    const d = modInverse(e, lambda);
    return { n, e, d, lambda, emBits: n.toString(2).length - 1 };
}

function gcdBig(a: bigint, b: bigint): bigint {
    let x = a;
    let y = b;
    while (y !== 0n) {
        const t = x % y;
        x = y;
        y = t;
    }
    return x;
}

/** Sign a message, returning the signature as a BigInt. */
export function rsaPssSign(message: number[], key: ToyRsaKey, salt: number[]): bigint {
    const messageHash = toyHash(message);
    const em = pssEncode(messageHash, key.emBits, salt);
    let value = 0n;
    for (const byte of em) value = (value << 8n) | BigInt(byte);
    return powMod(value, key.d, key.n);
}

/** Verify a PSS signature on a message. */
export function rsaPssVerify(message: number[], signature: bigint, key: ToyRsaKey): boolean {
    const emBits = key.emBits;
    const emLen = Math.ceil(emBits / 8);
    const recovered = powMod(signature, key.e, key.n);
    const em: number[] = new Array(emLen).fill(0);
    let value = recovered;
    for (let i = emLen - 1; i >= 0; i -= 1) {
        em[i] = Number(value & 0xffn);
        value >>= 8n;
    }
    return pssVerify(em, toyHash(message), emBits, S_LEN);
}

function makeBars(hashByte: number, signatureSample: number, verdict: number): VisualEntity[] {
    return [hashByte, signatureSample, verdict].map((value, index) => ({
        id: `val-${index}`,
        type: "bar" as const,
        label: `${value}`,
        value,
        state: (index === 2 ? "sorted" : "active") as EntityState,
        x: 0,
        y: 0,
        width: 0,
        height: 0,
        metadata: { index, role: ["message hash", "signature residue", "verified"][index] ?? "" },
    }));
}

function* run(input: unknown): Generator<VisualFrame, void, unknown> {
    const task = (input as { message?: number[]; salt?: number[] } | null) ?? {};
    const message = task.message ?? [10, 20, 30, 40, 50, 60];
    const salt = task.salt ?? [1, 2, 3, 4, 5, 6, 7, 8];

    let step = 0;
    const key = rsaPssKeygen();
    yield {
        stepNumber: step,
        entities: makeBars(0, 0, 0),
        edges: [],
        description: "Generated a toy RSA key with a modulus wide enough for PSS padding.",
        codeLineNumber: 0,
        layout: "array",
        meta: { n: key.n.toString(), emBits: key.emBits },
    };
    step += 1;

    const messageHash = toyHash(message);
    yield {
        stepNumber: step,
        entities: makeBars(messageHash[0] ?? 0, 0, 0),
        edges: [],
        description: "Hashed the message with the teaching hash to a fixed-size digest.",
        codeLineNumber: 1,
        layout: "array",
        meta: { digest: messageHash },
    };
    step += 1;

    const em = pssEncode(messageHash, key.emBits, salt);
    yield {
        stepNumber: step,
        entities: makeBars(em[0] ?? 0, 0, 0),
        edges: [],
        description: `Built the encoded message using a salt and an MGF1 mask (${em.length} bytes).`,
        codeLineNumber: 2,
        layout: "array",
        meta: { emLen: em.length, salt: em.slice(-9, -1) },
    };
    step += 1;

    const signature = rsaPssSign(message, key, salt);
    const sample = Number(signature % 1000000n);
    yield {
        stepNumber: step,
        entities: makeBars(messageHash[0] ?? 0, sample, 0),
        edges: [],
        description: "Applied the private RSA operation to produce the signature.",
        codeLineNumber: 3,
        layout: "array",
        meta: { signature: signature.toString() },
    };
    step += 1;

    const verified = rsaPssVerify(message, signature, key);
    yield {
        stepNumber: step,
        entities: makeBars(messageHash[0] ?? 0, sample, verified ? 1 : 0),
        edges: [],
        description: `Done: verification ${verified ? "accepts" : "rejects"} the signature. Toy scheme, not secure.`,
        codeLineNumber: 4,
        layout: "array",
        meta: { verified, n: key.n.toString() },
    };
}

const module: AlgorithmModule = {
    education: {
        intuition:
            "PSS turns a hash into a padded block before signing: it mixes in a random salt, hashes the salted message, and hides the salt with a mask derived from that hash. Verification unmasks the salt and re-derives everything. The randomness means signing the same message twice gives different signatures, and the structure is what lets proofs reduce forgery to breaking RSA.",
        invariants: [
            "The encoded message always ends with the separator byte 0xbc.",
            "MGF1 derives the mask deterministically from the inner hash.",
            "A valid signature recovers padding zeros, a single 0x01, and a salt that reproduces the hash.",
        ],
        correctness:
            "RSA exponentiation with the private and public exponents cancels modulo n, so a genuine signature recovers the encoded message exactly. Verification then checks the fixed structure and recomputes the salted hash; any tampering to the message or signature either changes the exponentiation result or breaks the separator, padding, or hash equality. The teaching hash is deterministic and the encoding follows the PSS layout, so these checks behave exactly as the standard describes, though with no security.",
        complexityRationale:
            "Signing and verifying each use one modular exponentiation with about log n bits, costing O(log n) multiplications on O(log n)-bit integers. Masking and hashing the encoded message are linear in the encoded length.",
        uses: [
            "Digital signatures with provable security reductions",
            "Certificate and software-signing protocols",
            "Any setting that needs randomized, non-repudiable signatures",
        ],
        references: [
            "Bellare and Rogaway, The Exact Security of Digital Signatures: How to Sign with RSA and Rabin, 1996",
            "RFC 8017, PKCS #1: RSA Cryptography Specifications, Section 9.1",
        ],
        workedExample:
            "With a message digest and an eight-byte salt, the encoder forms eight zero bytes, the digest, and the salt, hashes them, masks a block containing padding and the salt, and appends the separator. The RSA private exponent is applied to this block. Verification recovers the block, unmasks it, finds the salt, and confirms that hashing the salted digest reproduces the stored hash.",
    },
    id: "rsa-pss",
    name: "RSA-PSS Signatures (Toy Model)",
    category: "cryptography-security",
    complexity: { time: "O(log n)", space: "O(emLen)" },
    defaultInput: { message: [10, 20, 30, 40, 50, 60], salt: [1, 2, 3, 4, 5, 6, 7, 8] },
    visualType: "array",
    run,
    pseudocode: [
        "generate a toy RSA modulus and exponent pair",
        "hash the message to a fixed-size digest",
        "build the encoded message with salt and MGF1 mask",
        "raise the encoded message to the private exponent",
        "recover the encoded message with the public exponent",
        "unmask, check padding, and recompute the salted hash",
        "done: report whether the signature verifies",
    ],
};

export default module;
